import * as crypto from 'node:crypto';
function main(): void {
  const c: any = crypto;
  const spkac = '';
  console.log(c.Certificate.exportChallenge(spkac).toString(), c.Certificate.verifySpkac(Buffer.from(spkac)), c.Certificate.verifySpkac(Buffer.from('AAAA')));
  console.log(c.Certificate.exportPublicKey(spkac).toString().split('\n')[0]);
  const cert: any = new c.Certificate();
  console.log(cert instanceof c.Certificate, cert.exportChallenge(spkac).toString(), typeof c.Certificate() === 'object');
  console.log(typeof c.constants.defaultCipherList, c.constants.defaultCoreCipherList.split(':')[0]);
  try { c.KeyObject.from({}); } catch (e: any) { console.log(e.code, e.message); }
}
